#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import sys
import types
import zlib
from pathlib import Path

EMBEDDED_MODULES = {
    "MI": """""",
    "OH": """""",
    "LA": """""",
    "OR": """""",
    "AR": """""",
}


def load_module(state: str):
    state = state.upper()
    if state not in EMBEDDED_MODULES:
        raise ValueError(f"Unsupported state: {state}")
    source = zlib.decompress(base64.b64decode(EMBEDDED_MODULES[state])).decode('utf-8')
    module_name = f"embedded_{state.lower()}"
    module = types.ModuleType(module_name)
    module.__dict__["__name__"] = module_name
    sys.modules[module_name] = module
    exec(compile(source, f"{module_name}.py", "exec"), module.__dict__)
    return module


def main() -> int:
    parser = argparse.ArgumentParser(description="Michigan, Ohio, Louisiana, Oregon, and Arkansas charity checker.")
    parser.add_argument("--state", required=True, help="State to run: MI, OH, LA, OR, or AR")
    parser.add_argument("--ein", default="", help="Organization EIN when required by the state")
    parser.add_argument("--name", default="", help="Organization name when required by the state")
    parser.add_argument("--headful", action="store_true", help="Show the browser window")
    parser.add_argument("--show-process", action="store_true", help="Show the browser and slow actions down")
    parser.add_argument("--slow-mo-ms", type=int, default=0, help="Slow motion delay in milliseconds")
    parser.add_argument("--artifacts-dir", default="artifacts", help="Folder for screenshot artifacts")
    parser.add_argument("--no-screenshot", action="store_true", help="Do not save a screenshot artifact")
    args = parser.parse_args()

    state = args.state.strip().upper()
    module = load_module(state)

    if args.show_process:
        args.headful = True
        if args.slow_mo_ms <= 0:
            args.slow_mo_ms = 500

    artifacts_dir = Path(args.artifacts_dir)

    with module.sync_playwright() as playwright:
        browser = playwright.chromium.launch(headless=not args.headful, slow_mo=args.slow_mo_ms)
        page = browser.new_page()
        try:
            if state == "MI":
                if not args.ein.strip():
                    raise ValueError("MI requires --ein")
                org = module.Organization(ein=args.ein.strip(), organization_name=args.name.strip())
                result = module.search_mi(page, org, artifacts_dir, args.no_screenshot)
            elif state == "OH":
                if not args.ein.strip():
                    raise ValueError("OH requires --ein")
                org = module.Organization(ein=args.ein.strip(), organization_name=args.name.strip())
                result = module.search_oh(page, org, artifacts_dir, args.no_screenshot)
            elif state == "LA":
                if not args.name.strip():
                    raise ValueError("LA requires --name")
                org = module.Organization(organization_name=args.name.strip())
                result = module.search_la(page, org)
            elif state == "OR":
                if not args.name.strip():
                    raise ValueError("OR requires --name")
                org = module.Organization(organization_name=args.name.strip(), ein=args.ein.strip())
                result = module.search_or(page, org)
            elif state == "AR":
                if not args.name.strip():
                    raise ValueError("AR requires --name")
                org = module.Organization(organization_name=args.name.strip(), ein=args.ein.strip())
                result = module.search_ar(page, org)
            else:
                raise ValueError(f"Unsupported state: {state}")
        finally:
            browser.close()

    print(f"State: {state}")
    if hasattr(result, 'organization_name'):
        print(f"Organization: {result.organization_name}")
    if hasattr(result, 'ein'):
        print(f"EIN: {getattr(result, 'ein', '')}")
    print(f"Status: {result.status}")
    print(f"Raw Status: {result.raw_status_text}")
    print(f"Source URL: {result.source_url}")
    print(f"Source Note: {result.source_note}")
    if result.error:
        print(f"Error: {result.error}")

    not_registered = getattr(module, 'STATUS_NOT_REGISTERED', None)
    unknown = getattr(module, 'STATUS_UNKNOWN', None)
    return 0 if result.success or result.status in {not_registered, unknown} else 1


if __name__ == "__main__":
    raise SystemExit(main())

